-- cpl_memory rows for the S653b side session (SkyGodwit's second session), 2026-11-14. One statement.
-- Every summary at most 400 characters (the table's check), measured by script when this file was written:
--   377, 385, 377, 285, 381, 324, 224, 225, 189; the longest is 385.
-- INSERT ... ON CONFLICT (slug) DO NOTHING (a replay is harmless), then the cpl_memory_log append, then the verify.
-- ROLLBACK (by slug; never by author):
--   delete from cpl_memory_log where memory_id in (select id from cpl_memory where slug in (<the slugs>));
--   delete from cpl_memory where slug in (<the slugs>);
-- No row is superseded. No row carries Sam's words: S653b's decisions are the conductor's (status proposed, for Sam to
-- revise on the sheet); the split itself is S653's row d-two-sessions-one-writer-s653.

-- ===========================================================================================================
-- STATEMENT 1 -- NOT RUN. The S653b conductor runs it as one execute_sql call and records RUN here.
-- ===========================================================================================================
insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-workplan-drop-current-two-steps-s653b','decision','workplan_goals.current goes in two steps: readers, then the drop','The S653b conductor: readers first (#3335 d640b01d: no code reads or writes the column; guard workplan_goals_current_column_guard_test), then the drop via kb/migrations/.apply (pushed 20:37Z). No data lost: reads at 18:41Z and 20:36Z show 72 rows, current non-null in one (id 3, value 2), equal to cur_2025_26 in all 72. The migration refuses otherwise; _rollback.sql restores.',array['workplan-annual-goals','migration','decision'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('d-key-readers-environment-groups-s653b','decision','Service-key readers move into live-counts by group, main-only runs first','The S653b conductor: one environment, live-counts as it stands. A workflow moves only when every run of it is on main (triggers, last 30 runs, no playbook dispatching it on a branch). Order: group 2 (14 jobs), then daily-dashboard.yml in its own PR after group 1 ran on its schedules, then the 12 branch-run files. Sam removes the repository copy of the key only when PENDING is empty.',array['governance-team-enablement','secrets','decision'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('d-test-counts-only-on-pull-request-s653b','decision','A test counts as run only in a pull_request workflow step that can fail','The S653b conductor, #3337 (fe1c4f0e): a test counts only when a workflow with a pull_request trigger names it in a step that can fail. continue-on-error, if: false, a line ending || true, || : or || exit 0, a test left of &&, or set +e without the collector do not count; grouped steps use scripts/test_group.sh. Guard tests/every_test_runs_test.py; three files stay excepted.',array['governance-team-enablement','ci','decision'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('honors-rows-review-three-verdict-s653b','fact','Review three of #3315 (Honors rows): lump and sequence failed a third round','S653b ran review three of #3315 for the S653 conductor: nine agents on head 4b4f2e4b; the finding list is PR comment 6882899324. Step 2 may not apply as designed; the lump and sequence classes failed a third round, so their design is replaced rather than patched again (the S652 rule).',array['commons','honors','review','fact'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('fact-sheet-public-header-live-s653b','fact','The Fact Sheet carries the public header; the Veteran map''s logos are 480px','S653b, #3333 (908d9b8d), read live 19:51Z 2026-11-14: fact-sheet/index.html (no generator writes it) carries the public header between the skip link and the masthead; --cplh-* roles map onto factsheet.css; the masthead is a div (one banner); it never prints; no embed case. The Veteran map embeds 480px logos (225,221 to 166,896 bytes). Guard tests/factsheet_public_header.test.js.',array['library','public-header','fact'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('key-rotation-two-copies-until-pending-empty-s653b','risk','Until PENDING is empty, a service-key rotation updates two copies','COBIx on #3334: until the PENDING list in tests/service_key_environment_test.py is empty, rotating the Supabase service key means updating both copies, the live-counts environment''s and the repository''s; one alone fails half the workflows. After #3334: 38 workflow files read the key, 10 jobs in the environment, 32 pending.',array['governance-team-enablement','secrets','risk'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('p-dirty-pr-starts-no-ci-s653b','pitfall','A PR in conflict with main starts no pull_request run','S653b: a PR that conflicts with main starts no pull_request run, so get_check_runs reads 0 and the merge state is dirty. That is not a pending test. Merge main into the branch first, then read the check runs on the new head.',array['conductor','ci','pitfall'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('p-dependency-map-conflicts-serial-merges-s653b','pitfall','Each PR adding a test or workflow puts the other open PRs in conflict','S653b: every PR that adds a test or a workflow rebuilds the dependency map, so each merge puts the other open PRs in conflict. Merge in sequence and bring only the next one up to main; five PRs cost four extra merges of main.',array['conductor','dependency-map','pitfall'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14'),
('p-list-events-floods-context-s653b','pitfall','list_events on a busy session floods the context','S653b: list_events on a busy session returned about 40,000 tokens of subagent events and thinking signatures. Ask for few events (a small limit and kinds), or read the saved file by script.',array['conductor','context','pitfall'],'proposed','S653b documents; docs/session_654_handoff.md addendum and the lane files',null,null,'SkyGodwit side session (S653b)',date '2026-11-14')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyGodwit side session (S653b)', 'create', 'S653b documents (2026-11-14)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-workplan-drop-current-two-steps-s653b','d-key-readers-environment-groups-s653b','d-test-counts-only-on-pull-request-s653b','honors-rows-review-three-verdict-s653b','fact-sheet-public-header-live-s653b','key-rotation-two-copies-until-pending-empty-s653b','p-dirty-pr-starts-no-ci-s653b','p-dependency-map-conflicts-serial-merges-s653b','p-list-events-floods-context-s653b')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-workplan-drop-current-two-steps-s653b','d-key-readers-environment-groups-s653b','d-test-counts-only-on-pull-request-s653b','honors-rows-review-three-verdict-s653b','fact-sheet-public-header-live-s653b','key-rotation-two-copies-until-pending-empty-s653b','p-dirty-pr-starts-no-ci-s653b','p-dependency-map-conflicts-serial-merges-s653b','p-list-events-floods-context-s653b')
group by m.slug, m.summary order by m.slug;
